} else {
  // Privacy: do NOT greet by name — let GPT verify identity first
  greeting = 'Thank you for calling 3 6 0 Group. ' +
    'I see you have called us before. For security, may I confirm your name please?';
}

const twiml = '<Response>' +
  '<Gather input="speech" language="en-US" speechTimeout="auto" action="https://chi-360dmmc.app.n8n.cloud/webhook/twilio-voice?retry=1">' +
    '<Say voice="' + selectedVoice + '" language="en-US">' + greeting + '</Say>' +
  '</Gather>' +
  '<Redirect>https://chi-360dmmc.app.n8n.cloud/webhook/twilio-voice?retry=1</Redirect>' +
'</Response>';

return [{ json: { twiml } }];

// Starter FAQ Reply
const faqAnswer = $json?.answer;
const aiReply =
  faqAnswer ||
  $json?.choices?.[0]?.message?.content ||
  $json?.message?.content ||
  "Sorry, I didn't catch that.";

const selectedVoice = $('Merge1').first().json.selected_voice || "Polly.Matthew-Neural";

// FAQ replies never trigger end call - always loop back
