<Response>
    <Gather input="speech" language="en-US" speechTimeout="auto" action="https://chi-360dmmc.app.n8n.cloud/webhook/twilio-voice?retry=1">
        <Say voice="${selectedVoice}">${aiReply}</Say>
    </Gather>
    <Redirect>https://chi-360dmmc.app.n8n.cloud/webhook/twilio-voice?retry=1</Redirect>
</Response>
`;
return [{ json: { twiml } }];

// Cache QNA: store FAQ rows in workflow static data
const store = $getWorkflowStaticData('global');

// Pull all incoming items (each item is one FAQ row JSON)
const rows = $input.all().map(i => i.json);

// Store
store.faqRows = rows;

// Return something small for visibility
return [{ json: { ok: true, cached: rows.length } }];

