const user = String(userRaw).toLowerCase().trim();

// Dice similarity on bigrams
function dice(a, b) {
  const grams = (s) => {
    const z = String(s).replace(/[^a-z0-9 ]/gi, '').toLowerCase();
    const out = [];
    for (let i = 0; i < z.length - 1; i++) out.push(z.slice(i, i + 2));
    return out;
  };

  const A = grams(a), B = grams(b);
  if (!A.length || !B.length) return 0;

  const m = new Map();
  for (const x of A) m.set(x, (m.get(x) || 0) + 1);

  let inter = 0;
  for (const x of B) {
    const c = m.get(x) || 0;
    if (c > 0) { inter++; m.set(x, c - 1); }
  }

  return (2 * inter) / (A.length + B.length);
}

let best = { score: 0, row: null };

